"""One-time independent review of home-care items and cross-field overlaps."""
import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'data/original/community.json'
d=json.loads(p.read_text(encoding='utf-8'))
updates={
1:('市町村および特別区|都道府県|国|全国健康保険協会','介護保険では市町村・特別区が保険者となり、認定や給付を担う。|都道府県は市町村への支援などを担うが、介護保険の保険者ではない。|国は制度の基本的枠組みなどを担うが、保険者は市町村・特別区である。|協会けんぽは医療保険の保険者で、介護保険の保険者とは区別する。'),
5:('市区町村の介護保険担当窓口|加入する健康保険組合|都道府県の保健所|年金事務所','要介護・要支援認定は、保険者である市区町村に申請する。|健康保険組合への医療保険の手続きと、介護保険の認定申請は別である。|保健所は地域の公衆衛生活動を担うが、要介護認定の申請先ではない。|年金事務所は年金の手続きを扱い、介護認定の申請先ではない。'),
8:('自宅での入浴や排泄の直接介助|医師による自宅での継続的な診療|施設に宿泊する間の日常生活の支援|ケアプラン作成とサービス調整','訪問介護の身体介護に当たる内容で、居宅介護支援の中心業務とは異なる。|訪問診療の内容であり、居宅介護支援が診療そのものを行うわけではない。|短期入所で行う支援であり、居宅介護支援は利用を含む計画や調整を担う。|介護支援専門員が本人の状況に応じた計画作成や事業者との調整を行う。'),
10:('介護支援専門員による看護処置の指示|主治医の指示|要介護認定の結果のみ|退院時の看護要約のみ','ケアマネジャーはサービスを調整するが、医療上の看護処置を指示する主治医の代わりにはならない。|訪問看護は主治医の指示に基づき実施する。|要介護認定はサービス利用に関わるが、それだけで主治医の指示を代替できない。|看護要約は継続に重要な資料だが、主治医の訪問看護指示とは異なる。'),
13:('入浴・排泄等の身体介護や生活援助|主治医として行う計画的な診療|看護師が指示に基づき行う褥瘡処置|理学療法士が訪問して行うリハビリテーション','訪問介護では本人の生活を支える身体介護や生活援助を行う。|医師による訪問診療と訪問介護は異なるサービスである。|看護師による医療的な処置は訪問看護として行われ、訪問介護とは区別する。|専門職による訪問リハビリテーションは訪問介護とは区別する。'),
16:('自宅に訓練担当者が訪問して動作練習を行う|施設に数日間宿泊し生活支援を受ける|自宅へ浴槽を運び入れて入浴を支える|施設へ通い心身機能の維持回復に向け訓練する','担当者が自宅を訪れるのは訪問リハビリテーションである。|宿泊して短期間の支援を受けるのは短期入所である。|浴槽を自宅へ持参するのは訪問入浴介護の内容である。|通所リハビリテーションでは施設に通って専門的な訓練を受ける。'),
17:('短期入所|通所介護|訪問介護|居宅療養管理指導','短期間宿泊して生活を支えるため、介護者の入院時の代替支援に利用できる。|通所介護は通常日中の支援で、数日間の宿泊を伴う支援とは異なる。|訪問介護は自宅を訪れる支援で、この設問の施設宿泊には該当しない。|専門職が在宅療養の管理や助言を行うもので、宿泊サービスではない。'),
18:('通所・訪問・長期入所|通い・訪問・泊まり|訪問診療・訪問歯科診療・訪問薬剤管理|通所介護・介護認定・住宅改修','生活拠点を移す長期入所ではなく、在宅を支える泊まりを組み合わせる。|通いを中心に、状況や希望に合わせて訪問・泊まりを組み合わせる。|医療機関等による訪問サービスの列挙で、小規模多機能型居宅介護の構成ではない。|介護認定や住宅改修は、小規模多機能型の三つの支援方法ではない。'),
26:('病棟で実施した処置の時刻だけ|本人の目標と医療・介護の継続方法|退院後の担当看護師の氏名だけ|介護保険の認定結果だけ','処置の時刻だけでは、生活で必要な支援や急変時対応を共有できない。|目標や必要な支援、役割を共有し、退院後も継続できるよう調整する。|担当者の把握に加え、本人の状態や継続すべき支援内容が必要である。|認定結果は参考になるが、医療と生活の具体的な支援方針も共有する。'),
35:('支援者・避難先・避難方法|主治医名と処方内容のみ|行政の防災計画の全文のみ|本人が選ぶ避難所名のみ','本人の状況に即して、誰がどこへどう避難を支援するかを具体化する。|医療情報だけでなく、移動方法や支援体制を決める必要がある。|地域の一般計画だけでなく、本人に必要な支援を個別に記載する。|避難先に加え、そこまでの移動や支援者も計画する。'),
63:('療養者の身体機能を集中的に訓練する|要介護認定の調査を代行する|介護者に一時的な休息を提供する|福祉用具の適合性を評価する','訓練が行われる場合もあるが、レスパイトの主目的は介護者の休息である。|認定調査の代行はレスパイトケアの目的ではない。|一時的に介護を代替して介護者の休息や負担軽減を図る。|用具の評価と、介護者に休息を提供するレスパイトケアは区別する。'),
69:('住民の健康相談・保健指導等|入院患者への継続的な手術と治療|介護保険の要介護度の最終決定|成年後見人の選任','市町村保健センターでは住民の健康相談や保健指導、健康診査などを行う。|入院診療を行う病院の役割とは異なる。|要介護認定の手続きは介護保険の保険者が行う。|成年後見人の選任は家庭裁判所の手続きである。'),
72:('地域包括支援センター|介護老人保健施設|児童家庭支援センター|精神保健福祉センター','主に高齢者の総合相談や権利擁護等を担う機関である。|介護やリハビリテーション等を提供する施設で、広域的な精神保健の専門機関ではない。|児童や家庭に関する相談支援を担い、この設問の広域的な精神保健専門機関とは異なる。|精神保健福祉に関する専門的相談や地域の支援を担う。'),
86:('訪問入浴介護|訪問歯科診療等|居宅介護支援だけ|通所介護の入浴担当者','入浴支援では義歯の診査や調整は行えない。|義歯や口腔内の状態を評価し、食べやすさの改善につなげる。|ケアマネジャーとの連携も大切だが、義歯の評価には歯科専門職につなぐ必要がある。|生活支援職から情報を得ることはできるが、義歯の診療は歯科へ相談する。')
}
for q in d['questions']:
 n=int(q['id'][-3:])
 if n in updates:
  q['choices'],q['notes']=[x.split('|') for x in updates[n]]
  q['review_note']+=' 二次確認：関連する制度・支援の取り違えを誤答に用いて再構成。'
replacement={
37:('留置カテーテルの採尿','在宅で尿道留置カテーテルを使用する人に尿培養の指示が出た。訪問看護師の採尿方法はどれか。','尿バッグにたまった古い尿を採る|接続を外して尿を容器に受ける|採尿ポートを消毒し滅菌器具で新鮮な尿を採る|バッグの排出口に容器を接触させて採る','バッグ内の古い尿は培養用の新鮮な検体としては適さない。|不必要に接続を外すと閉鎖系が破綻し、汚染の機会を増やす。|培養用の少量尿は、消毒した採尿ポートから無菌的に採取する。|排出口と非滅菌容器の接触は汚染につながり、培養尿の適切な採取方法ではない。'),
38:('留置中の陰部清潔','尿道留置カテーテルを使用する在宅療養者に、特別な処置の指示はない。尿道口周囲の日常的な清潔ケアはどれか。','毎日消毒薬を用いて予防的に消毒する|感染予防のため抗菌薬入り軟膏を毎日塗る|カテーテル留置中は陰部洗浄を控える|入浴や清拭時に通常の洗浄で清潔を保つ','感染予防だけを目的に、留置中の尿道口周囲を日常的に消毒することは勧められない。|特別な指示なく抗菌薬軟膏を予防的に使用する方法ではない。|留置中も清潔は必要であり、通常の洗浄を続ける。|日常的な洗浄で清潔を保ち、異常があれば評価する。'),
39:('長期カテーテルと予防抗菌薬','長期留置カテーテルを使用中で、感染症状も抗菌薬の適応もない在宅療養者の家族が、毎日抗菌薬を飲めば感染を防げるかと尋ねた。説明はどれか。','留置しているだけを理由に抗菌薬を常用することは勧められない|無症状でも留置期間中は毎日抗菌薬が必要である|抗菌薬を飲めば閉鎖式回路を保つ必要はない|抗菌薬を飲めば留置継続の適応確認は不要である','臨床的な適応がない場合、カテーテル関連感染を防ぐための全身抗菌薬の常用は勧められない。|無症状の留置だけで予防的な連日投与を選ぶのではなく、必要性を医師が判断する。|抗菌薬の使用の有無にかかわらず、閉鎖性の保持など基本的な管理が必要である。|不要な留置を避けることは感染予防に重要で、抗菌薬で置き換えられない。')
}
for q in d['questions']:
 n=int(q['id'][-3:])
 if n in replacement:
  topic,stem,choices,notes=replacement[n]
  q.update(topic=topic,question=stem,choices=choices.split('|'),notes=notes.split('|'),review_note='二次確認：基礎看護学との学習項目重複を解消。CDC CAUTI推奨 III.U.1、III.G、III.Fを確認。')
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Revised',len(updates)+len(replacement),'community items')
